+/** Returns true if the dtype is valid. */
+export function isValidDtype(dtype: DataType): boolean {
+  return dtype === 'bool' || dtype === 'complex64' || dtype === 'float32' ||
+      dtype === 'int32' || dtype === 'string';
+}
