+  //  implementations.
+  //  2. It doesn't work with framework that uses zone.js. zone.js monkey patch
+  //  the async calls, so it is possible the obj (patched) is comparing to a
+  //  pre-patched Promise.
+  return object && object.then && typeof object.then === 'function';
+}

